#include <map>
#include <new>
#include <stdexcept>
#include <string>

class StoneBag
{
public:
    void add(const std::string& name, int weight)
    {
        if (name.empty() || weight <= 0) throw std::invalid_argument("bad stone");
        m_stones[name] += weight;
    }
    int count() const { return static_cast<int>(m_stones.size()); }
    int totalWeight() const
    {
        int total{ 0 };
        for (const auto& [name, weight] : m_stones) total += weight;
        return total;
    }
    std::string heaviest() const
    {
        if (m_stones.empty()) throw std::logic_error("empty bag");
        auto best{ m_stones.begin() };
        for (auto it{ m_stones.begin() }; it != m_stones.end(); ++it) if (it->second > best->second) best = it;
        return best->first;
    }
private:
    std::map<std::string, int> m_stones;
};

enum BagResult : int { BAG_OK = 0, BAG_INVALID_ARGUMENT = 1, BAG_EMPTY = 2, BAG_OUT_OF_MEMORY = 3, BAG_FAILED = 4 };
struct BagHandle;

extern "C" int bag_create(BagHandle** out) { return BAG_FAILED; }
extern "C" int bag_destroy(BagHandle* bag) { return BAG_FAILED; }
extern "C" int bag_add(BagHandle* bag, const char* name, int weight) { return BAG_FAILED; }
extern "C" int bag_count(const BagHandle* bag, int* out) { return BAG_FAILED; }
extern "C" int bag_total_weight(const BagHandle* bag, int* out) { return BAG_FAILED; }
extern "C" int bag_heaviest(const BagHandle* bag, char* buffer, int capacity, int* lengthOut) { return BAG_FAILED; }
extern "C" int bag_live_count() { return 0; }

solution.solution.cpp:
#include <cstring>
#include <map>
#include <new>
#include <stdexcept>
#include <string>

class StoneBag
{
public:
    void add(const std::string& name, int weight)
    {
        if (name.empty() || weight <= 0) throw std::invalid_argument("bad stone");
        m_stones[name] += weight;
    }
    int count() const { return static_cast<int>(m_stones.size()); }
    int totalWeight() const
    {
        int total{ 0 };
        for (const auto& [name, weight] : m_stones) total += weight;
        return total;
    }
    std::string heaviest() const
    {
        if (m_stones.empty()) throw std::logic_error("empty bag");
        auto best{ m_stones.begin() };
        for (auto it{ m_stones.begin() }; it != m_stones.end(); ++it) if (it->second > best->second) best = it;
        return best->first;
    }
private:
    std::map<std::string, int> m_stones;
};

enum BagResult : int { BAG_OK = 0, BAG_INVALID_ARGUMENT = 1, BAG_EMPTY = 2, BAG_OUT_OF_MEMORY = 3, BAG_FAILED = 4 };

// The handle is the class itself, seen from outside only as an incomplete type.
struct BagHandle { StoneBag bag; };

namespace
{
    int g_live{ 0 };

    struct EmptyBag {};

    template <typename Fn>
    int guarded(Fn&& body) noexcept
    {
        try { body(); return BAG_OK; }
        catch (const EmptyBag&) { return BAG_EMPTY; }
        catch (const std::invalid_argument&) { return BAG_INVALID_ARGUMENT; }
        catch (const std::bad_alloc&) { return BAG_OUT_OF_MEMORY; }
        catch (...) { return BAG_FAILED; }
    }

    void need(const void* p) { if (!p) throw std::invalid_argument("null"); }
}

extern "C" int bag_create(BagHandle** out)
{
    return guarded([&] {
        need(out);
        *out = new BagHandle{};
        ++g_live;
    });
}

extern "C" int bag_destroy(BagHandle* bag)
{
    return guarded([&] {
        if (!bag) return;
        delete bag;
        --g_live;
    });
}

extern "C" int bag_add(BagHandle* bag, const char* name, int weight)
{
    return guarded([&] {
        need(bag); need(name);
        bag->bag.add(name, weight);
    });
}

extern "C" int bag_count(const BagHandle* bag, int* out)
{
    return guarded([&] { need(bag); need(out); *out = bag->bag.count(); });
}

extern "C" int bag_total_weight(const BagHandle* bag, int* out)
{
    return guarded([&] { need(bag); need(out); *out = bag->bag.totalWeight(); });
}

extern "C" int bag_heaviest(const BagHandle* bag, char* buffer, int capacity, int* lengthOut)
{
    return guarded([&] {
        need(bag); need(lengthOut);
        if (bag->bag.count() == 0) throw EmptyBag{};
        const std::string name{ bag->bag.heaviest() };
        const int length{ static_cast<int>(name.size()) };
        if (buffer && capacity >= 1)
        {
            const int copy{ length < capacity - 1 ? length : capacity - 1 };
            std::memcpy(buffer, name.data(), static_cast<std::size_t>(copy));
            buffer[copy] = '\0';
        }
        *lengthOut = length;
    });
}

extern "C" int bag_live_count() { return g_live; }

unitTests:
TEST("create, use, destroy") {
    BagHandle* b = nullptr;
    CHECK_EQ(bag_create(&b), int(BAG_OK)); CHECK(b != nullptr);
    CHECK_EQ(bag_add(b, "basalt", 5), int(BAG_OK)); CHECK_EQ(bag_add(b, "granite", 8), int(BAG_OK)); CHECK_EQ(bag_add(b, "basalt", 4), int(BAG_OK));
    int n = 0; CHECK_EQ(bag_count(b, &n), int(BAG_OK)); CHECK_EQ(n, 2);
    int w = 0; CHECK_EQ(bag_total_weight(b, &w), int(BAG_OK)); CHECK_EQ(w, 17);
    CHECK_EQ(bag_destroy(b), int(BAG_OK));
}
TEST("live count") {
    const int before = bag_live_count();
    BagHandle* a = nullptr; BagHandle* b = nullptr;
    bag_create(&a); bag_create(&b);
    CHECK_EQ(bag_live_count(), before + 2);
    bag_destroy(a); CHECK_EQ(bag_live_count(), before + 1);
    bag_destroy(b); CHECK_EQ(bag_live_count(), before);
}
TEST("bad stones do not throw") {
    BagHandle* b = nullptr; bag_create(&b);
    CHECK_EQ(bag_add(b, "", 3), int(BAG_INVALID_ARGUMENT)); CHECK_EQ(bag_add(b, "x", 0), int(BAG_INVALID_ARGUMENT)); CHECK_EQ(bag_add(b, nullptr, 3), int(BAG_INVALID_ARGUMENT));
    bag_destroy(b);
}
TEST("null handles and outputs") {
    int n = 5;
    CHECK_EQ(bag_create(nullptr), int(BAG_INVALID_ARGUMENT)); CHECK_EQ(bag_count(nullptr, &n), int(BAG_INVALID_ARGUMENT)); CHECK_EQ(n, 5);
    CHECK_EQ(bag_add(nullptr, "x", 1), int(BAG_INVALID_ARGUMENT)); CHECK_EQ(bag_destroy(nullptr), int(BAG_OK));
    BagHandle* b = nullptr; bag_create(&b); CHECK_EQ(bag_total_weight(b, nullptr), int(BAG_INVALID_ARGUMENT)); bag_destroy(b);
}
TEST("heaviest through a buffer") {
    BagHandle* b = nullptr; bag_create(&b); bag_add(b, "basalt", 5); bag_add(b, "granite", 8);
    char buf[16]; int len = 0;
    CHECK_EQ(bag_heaviest(b, buf, 16, &len), int(BAG_OK)); CHECK_EQ(len, 7); CHECK_EQ(std::string(buf), std::string("granite"));
    char small[4]; CHECK_EQ(bag_heaviest(b, small, 4, &len), int(BAG_OK)); CHECK_EQ(std::string(small), std::string("gra")); CHECK_EQ(len, 7);
    len = 0; CHECK_EQ(bag_heaviest(b, nullptr, 0, &len), int(BAG_OK)); CHECK_EQ(len, 7);
    CHECK_EQ(bag_heaviest(b, buf, 16, nullptr), int(BAG_INVALID_ARGUMENT));
    bag_destroy(b);
}
TEST("empty bag") { BagHandle* b = nullptr; bag_create(&b); char buf[8]; int len = 99; CHECK_EQ(bag_heaviest(b, buf, 8, &len), int(BAG_EMPTY)); CHECK_EQ(len, 99); bag_destroy(b); }

